class Solution {
    public int greatestCommonDivisor(int a, int b) {
        if (a == 0 || b == 0) {
            return Math.abs(a - b); // Return the absolute difference instead of sum
        }
        if (a == b) {
            return a;
        }
        if (a > b) {
            return greatestCommonDivisor(a % b, a);
        } else {
            return greatestCommonDivisor(a, b % b);
        }
    }
