class Solution {
    public int largestPrimeFactor(int n) {
        int largest = 1;
        for (int j = 2; j * j <= n; j++) { // Optimization: only check up to sqrt(n)
            if (n % j == 0) {
                boolean is_prime = true;
                for (int i = 2; i < j; i++) {
                    if (n % i == 0) {
                        is_prime = false;
                        break;
                    }
                }
                if (is_prime) {
                    largest = Math.max(largest, j);
                }
                n /= j; // Divide n by j to handle cases where j is a factor of n more than once
            }
        }
        if (n > 1) { // Check if n is a prime number greater than sqrt(n)
            largest = Math.max(largest, n);
        }
        return largest;
    }
}
