class Solution {
    public int multiply(int a, int b) {
        // Handle negative numbers separately
        boolean isNegative = (a < 0 && b > 0) || (a > 0 && b < 0);

        // Convert both numbers to positive for simplicity
        a = Math.abs(a);
        b = Math.abs(b);

        // Calculate the product of the digits
        int product = 0;
        while (b > 0) {
            int digit = b % 10;
            product += digit * a;
            b /= 10;
        }

        // Apply the sign back to the result
        if (isNegative) {
            product = -product;
        }

        return product;
    }
}
