import java.util.*;
import java.lang.*;

class Solution {
    public boolean rightAngleTriangle(int a, int b, int c) {
        // Check if any of the sides is zero or negative
        if (a <= 0 || b <= 0 || c <= 0) {
            return false;
        }

        // Sort the sides to ensure c is the longest side
        int[] sides = {a, b, c};
        Arrays.sort(sides);

        // Check if it's a right-angled triangle using the Pythagorean theorem
        return sides[2] * sides[2] == sides[0] * sides[0] + sides[1] * sides[1];
    }
}
